// components/Home.js
import { useState, useEffect } from "react";
import { logout, getCurrentUser, assignRole } from "../api/auth";
import { useNavigate } from "react-router-dom";
import "../styles/App.css";

export default function Home() {
    const navigate = useNavigate();
    const [currentUser, setCurrentUser] = useState(null);
    const [assignEmail, setAssignEmail] = useState("");
    const [assignRoleName, setAssignRoleName] = useState("ROLE_USER");
    const [message, setMessage] = useState("");
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const user = getCurrentUser();
        setCurrentUser(user);
    }, []);

    const handleLogout = () => {
        logout();
        navigate("/login");
    };

    const handleAssignRole = async (e) => {
        e.preventDefault();
        setMessage("");
        setError("");
        setLoading(true);

        if (!assignEmail || !assignRoleName) {
            setError("Заполните все поля");
            setLoading(false);
            return;
        }

        try {
            await assignRole(assignEmail, assignRoleName);
            setMessage(`Роль ${assignRoleName} успешно назначена пользователю ${assignEmail}`);
            setAssignEmail("");
        } catch (err) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    const hasRole = (role) => {
        return currentUser?.roles?.includes(role);
    };

    const getRoleDisplayName = (role) => {
        switch (role) {
            case "ROLE_ADMIN": return "Администратор";
            case "ROLE_COUNSELOR": return "Вожатый";
            case "ROLE_USER": return "Пользователь";
            case "ROLE_PARENT": return "Родитель"; // добавлено
            default: return role;
        }
    };


    return (
        <div className="home-container">
            <h1 className="title">Добро пожаловать!</h1>

            {currentUser && (
                <div className="user-info">
                    <p><strong>Email:</strong> {currentUser.email}</p>
                    <p><strong>Роли:</strong> {currentUser.roles?.map(getRoleDisplayName).join(", ") || "Нет ролей"}</p>
                </div>
            )}


            <div className="role-messages">
                {hasRole("ROLE_ADMIN") && (
                    <div className="message admin">
                        <h3>👑 Администратор</h3>
                        <p>У вас есть полный доступ ко всем функциям системы, включая управление ролями пользователей.</p>
                    </div>
                )}

                {hasRole("ROLE_COUNSELOR") && (
                    <div className="message counselor">
                        <h3>🎓 Вожатый</h3>
                        <p>Вы можете управлять отрядами, мероприятиями и просматривать статистику.</p>
                    </div>
                )}
                {hasRole("ROLE_PARENT") && (
                    <div className="message parent">
                        <h3>👪 Родитель</h3>
                        <p>Вы можете отслеживать прогресс и участие вашего ребёнка в системе.</p>
                    </div>
                )}

                {hasRole("ROLE_USER") && (
                    <div className="message user">
                        <h3>👤 Пользователь</h3>
                        <p>Базовый доступ к системе. Обратитесь к администратору для получения дополнительных прав.</p>
                    </div>
                )}

                {(!currentUser?.roles || currentUser.roles.length === 0) && (
                    <div className="message no-role">
                        <h3>❌ Нет ролей</h3>
                        <p>Обратитесь к администратору для получения доступа к системе.</p>
                    </div>
                )}
            </div>

            {hasRole("ROLE_ADMIN") && (
                <div className="role-management">
                    <h3>Управление ролями</h3>
                    <form onSubmit={handleAssignRole} className="form">
                        <input
                            type="email"
                            placeholder="Email пользователя"
                            value={assignEmail}
                            onChange={(e) => setAssignEmail(e.target.value)}
                            disabled={loading}
                        />
                        <select
                            value={assignRoleName}
                            onChange={(e) => setAssignRoleName(e.target.value)}
                            disabled={loading}
                        >
                            <option value="ROLE_USER">Обычный пользователь</option>
                            <option value="ROLE_COUNSELOR">Вожатый</option>
                            <option value="ROLE_ADMIN">Администратор</option>
                            <option value="ROLE_PARENT">Родитель</option> {/* добавлено */}
                        </select>
                        <button type="submit" disabled={loading}>
                            {loading ? "Назначение..." : "Назначить роль"}
                        </button>
                    </form>
                    {message && <p className="success">{message}</p>}
                    {error && <p className="error">{error}</p>}
                </div>
            )}

            <button onClick={handleLogout} className="logout-btn">
                Выйти из системы
            </button>
        </div>
    );
}
